//! Controls for the video interface hardware.
//!
//! The role of this subsystem is to display the external framebuffers (XFB) generated by
//! GX.

use core::sync::atomic::{AtomicPtr, Ordering};
use core::{convert::TryFrom, ffi::c_void, ptr};
use num_enum::TryFromPrimitive;

use crate::utils::Buf32;
use crate::ffi;

/// Function to call before or after a retrace.
pub type RetraceCallback = Option<fn(u32)>;

/// Multiplier to get real pixel size in bytes.
pub const DISPLAY_PIX_SZ: u32 = ffi::VI_DISPLAY_PIX_SZ;
pub const MAX_HEIGHT_DEBUG: u16 = ffi::VI_MAX_HEIGHT_DEBUG as u16;
pub const MAX_HEIGHT_EURGB60: u16 = ffi::VI_MAX_HEIGHT_EURGB60 as u16;
pub const MAX_HEIGHT_MPAL: u16 = ffi::VI_MAX_HEIGHT_MPAL as u16;
pub const MAX_HEIGHT_NTSC: u16 = ffi::VI_MAX_HEIGHT_NTSC as u16;
pub const MAX_HEIGHT_PAL: u16 = ffi::VI_MAX_HEIGHT_PAL as u16;
pub const MAX_WIDTH_DEBUG: u16 = ffi::VI_MAX_WIDTH_DEBUG as u16;
pub const MAX_WIDTH_EURGB60: u16 = ffi::VI_MAX_WIDTH_EURGB60 as u16;
pub const MAX_WIDTH_MPAL: u16 = ffi::VI_MAX_WIDTH_MPAL as u16;
pub const MAX_WIDTH_NTSC: u16 = ffi::VI_MAX_WIDTH_NTSC as u16;
pub const MAX_WIDTH_PAL: u16 = ffi::VI_MAX_WIDTH_PAL as u16;

/// Denotes video format standards for different regions.
#[derive(Clone, Copy, Debug, Eq, PartialEq, TryFromPrimitive)]
#[repr(u32)]
pub enum VideoFmt {
    /// Used in NA / JPN
    Ntsc = ffi::VI_NTSC,
    /// Used in Europe
    Pal = ffi::VI_PAL,
    /// Similar to NTSC, used in Brazil
    Mpal = ffi::VI_MPAL,
    /// Debug mode for NA / JPN. Special decoder needed.
    Debug = ffi::VI_DEBUG,
    /// Debug mode for EU. Special decoder needed.
    DebugPal = ffi::VI_DEBUG_PAL,
    /// RGB 60Hz, 480 lines (same timing + aspect as NTSC) used in Europe
    EuRgb60 = ffi::VI_EURGB60,
}

/// How the display image is refreshed
#[derive(Clone, Copy, Debug, Eq, PartialEq, TryFromPrimitive)]
#[repr(u32)]
pub enum ScanMode {
    /// Refreshes even lines, then odd lines
    Interlace = ffi::VI_INTERLACE,
    /// Refreshes only one set of lines every frame, leaving the other set black. Twice
    /// the refresh rate of interlace, but at half the vertical resolution.
    NonInterlace = ffi::VI_NON_INTERLACE,
    /// Every line gets refreshed every frame
    Progressive = ffi::VI_PROGRESSIVE,
}

/// Specifies the set of lines, or the *video field*, of the framebuffer.
#[derive(Clone, Copy, Debug, Eq, PartialEq, TryFromPrimitive)]
#[repr(u32)]
pub enum Field {
    /// Odd lines (1, 3, 5, ...)
    Lower = ffi::VI_FIELD_BELOW,
    /// Even lines (0, 2, 4, ...)
    Upper = ffi::VI_FIELD_ABOVE,
}

/// Whether XFB is in single-field or double-field mode
#[derive(Clone, Copy, Debug, Eq, PartialEq, TryFromPrimitive)]
#[repr(u32)]
pub enum XfbFieldMode {
    Single = ffi::VI_XFBMODE_SF,
    Double = ffi::VI_XFBMODE_DF,
}

/// Video and render settings
#[derive(Debug, Clone, Copy)]
pub struct RenderConfig {
    pub video_fmt: VideoFmt,
    pub scan_mode: ScanMode,
    /// Width of the framebuffer. This is the same between the embedded and external
    /// framebuffers.
    pub fb_width: u16,
    /// Height of the embedded framebuffer
    pub efb_height: u16,
    /// Height of the external framebuffer
    pub xfb_height: u16,
    /// Starting point of first pixel in VI
    pub vi_origin: (u16, u16),
    /// Width and height of the configured VI
    pub vi_size: (u16, u16),
    pub xfb_mode: XfbFieldMode,
    /// Whether field rendering is enabled
    pub field_rendering: bool,
    /// If `None`, anti-aliasing is disabled. Otherwise, specifies the sample pattern to
    /// be used for anti-aliasing. Valid range is 1 - 11 inclusive.
    pub sample_pattern: Option<[[u8; 2]; 12]>,
    /// Vertical filter coefficients. Valid coefficient range is 0 - 63 inclusive; sum
    /// should equal 64.
    pub v_filter: [u8; 7],
}

impl From<RenderConfig> for ffi::GXRModeObj {
    fn from(cfg: RenderConfig) -> ffi::GXRModeObj {
        ffi::GXRModeObj {
            viTVMode: (cfg.video_fmt as u32) << 2 | cfg.scan_mode as u32,
            fbWidth: cfg.fb_width,
            efbHeight: cfg.efb_height,
            xfbHeight: cfg.xfb_height,
            viXOrigin: cfg.vi_origin.0,
            viYOrigin: cfg.vi_origin.1,
            viWidth: cfg.vi_size.0,
            viHeight: cfg.vi_size.1,
            xfbMode: cfg.xfb_mode as u32,
            field_rendering: cfg.field_rendering as u8,
            aa: cfg.sample_pattern.is_some() as u8,
            sample_pattern: cfg.sample_pattern.unwrap_or_default(),
            vfilter: cfg.v_filter,
        }
    }
}

impl From<&RenderConfig> for ffi::GXRModeObj {
    fn from(cfg: &RenderConfig) -> ffi::GXRModeObj {
        (*cfg).into()
    }
}

impl From<ffi::GXRModeObj> for RenderConfig {
    fn from(obj: ffi::GXRModeObj) -> Self {
        RenderConfig {
            video_fmt: VideoFmt::try_from(obj.viTVMode >> 2).unwrap(),
            scan_mode: ScanMode::try_from(obj.viTVMode & 0x3).unwrap(),
            fb_width: obj.fbWidth,
            efb_height: obj.efbHeight,
            xfb_height: obj.xfbHeight,
            vi_origin: (obj.viXOrigin, obj.viYOrigin),
            vi_size: (obj.viWidth, obj.viHeight),
            xfb_mode: XfbFieldMode::try_from(obj.xfbMode).unwrap(),
            field_rendering: obj.field_rendering != 0,
            sample_pattern: (obj.aa != 0).then_some(obj.sample_pattern),
            v_filter: obj.vfilter,
        }
    }
}

impl RenderConfig {
    /// Takes a given render mode and returns a version that is reduced in size to account for overscan.
    ///
    /// See [`ogc_sys::GX_AdjustForOverscan()`] for more.
    pub fn adjust_for_overscan(&self, hor: u16, ver: u16) -> Self {
        let mut rmin: ffi::GXRModeObj = self.into();
        let mut rmout = core::mem::MaybeUninit::uninit();
        // SAFETY: rmout can be uninit
        unsafe {
            ffi::GX_AdjustForOverscan(&mut rmin, rmout.as_mut_ptr(), hor, ver);
            rmout.assume_init().into()
        }
    }
}


/// Initializes the VIDEO subsystem. Should be called early in `main()`.
pub fn init() {
    unsafe { ffi::VIDEO_Init() }
}
