/// Clears the framebuffer with the given render mode.
/// 
/// Color must be in YUYV format.
pub fn clear_framebuffer(rconf: &RenderConfig, fb: &mut Buf32, colour: u32) {
    let mut gxrmode: ffi::GXRModeObj = rconf.into();
    unsafe {
        ffi::VIDEO_ClearFrameBuffer(&mut gxrmode, fb.as_mut_ptr().cast(), colour);
    }
}

/// Returns the preferred render mode for the current configuration.
pub fn get_preferred_mode() -> RenderConfig {
    // SAFETY: passing NULL always gives us a valid pointer to valid static data.
    unsafe { *ffi::VIDEO_GetPreferredMode(ptr::null_mut()) }.into()
}

/// Configure the VI with the given render mode object.
pub fn configure(render_config: &RenderConfig) {
    let mut gxrmode = render_config.into();
    unsafe {
        ffi::VIDEO_Configure(&mut gxrmode);
    }
}

/// Flush the shadow registers to the drivers video registers.
pub fn flush() {
    unsafe { ffi::VIDEO_Flush() }
}

fn get_current_framebuffer() -> *mut c_void {
    unimplemented!()
}

/// Get current video line.
pub fn get_current_line() -> u32 {
    unsafe { ffi::VIDEO_GetCurrentLine() }
}

pub fn get_framebuffer_size(rmode: &RenderConfig) -> usize {
    let mut gxrmode = rmode.into();
    unsafe { ffi::VIDEO_GetFrameBufferSize(&mut gxrmode) as usize }
}

/// Get current configured video format, also called the TV mode.
pub fn get_video_fmt() -> VideoFmt {
    let mode = unsafe { ffi::VIDEO_GetCurrentTvMode() };
    VideoFmt::try_from(mode).unwrap()
}

/// Get the next video field.
pub fn get_next_field() -> Field {
    let next_field = unsafe { ffi::VIDEO_GetNextField() };
    Field::try_from(next_field).unwrap()
}

fn get_next_framebuffer() -> *mut c_void {
    unimplemented!()
}

/// Get the video scan mode.
pub fn get_scan_mode() -> ScanMode {
    let scan_mode = unsafe { ffi::VIDEO_GetVideoScanMode() };
    ScanMode::try_from(scan_mode).unwrap()
}

/// Check for a component cable. This returns true when a component cable (YPbPr) is
/// connected.
pub fn has_component_cable() -> bool {
    let component = unsafe { ffi::VIDEO_HaveComponentCable() };
    component == 1
}

/// Black out the VIDEO interface.
pub fn set_black(is_black: bool) {
    unsafe { ffi::VIDEO_SetBlack(is_black) }
}

/// Set the framebuffer for the next VI register update.
pub fn set_next_framebuffer(framebuffer: &Buf32) {
    unsafe {
        ffi::VIDEO_SetNextFramebuffer(framebuffer.as_ptr().cast_mut().cast());
    }
}

/// Set the right framebuffer for the next VI register update. This is used for 3D Gloves
/// for instance.
/// 
/// (No idea what libogc means by "3D gloves", and apparently this code has just Always
/// Been There.)
pub fn set_next_right_framebuffer(framebuffer: &Buf32) {
    unsafe {
        ffi::VIDEO_SetNextRightFramebuffer(framebuffer.as_ptr().cast_mut().cast());
    }
}

static POST_RETRACE_CB: AtomicPtr<fn(u32)> = AtomicPtr::null();

extern "C" fn post_retrace_callback_bridge(retrace_cnt: u32) {
    let cb_ptr = POST_RETRACE_CB.load(Ordering::Acquire);
    if ! cb_ptr.is_null() {
        // SAFETY: pointer is non-null and points to a valid rust function
        unsafe { (*cb_ptr)(retrace_cnt); }
    }
}

/// Sets the function to be called within the video interrupt handler after the VI
/// registers are updated.
/// 
/// Returns the previous callback function, if any.
pub fn set_post_retrace_callback(callback: RetraceCallback) -> RetraceCallback {
    let cb_ptr = match callback {
        None => {
            let _ = unsafe { ffi::VIDEO_SetPostRetraceCallback(None) };
            ptr::null_mut()
        }
        Some(mut f) => {
            let _ = unsafe { ffi::VIDEO_SetPostRetraceCallback(Some(post_retrace_callback_bridge)) };
            (&mut f) as *mut fn(u32)
        }
    };

    let prev_cb_ptr = POST_RETRACE_CB.swap(cb_ptr, Ordering::AcqRel);

    if prev_cb_ptr.is_null() {
        None
    } else {
        // SAFETY: pointer is non-null and always points to a valid rust function
        Some(unsafe { *prev_cb_ptr })
    }
}

static PRE_RETRACE_CB: AtomicPtr<fn(u32)> = AtomicPtr::null();

extern "C" fn pre_retrace_callback_bridge(retrace_cnt: u32) {
    let cb_ptr = PRE_RETRACE_CB.load(Ordering::Acquire);
    if ! cb_ptr.is_null() {
        // SAFETY: pointer is non-null and points to a valid rust function
        unsafe { (*cb_ptr)(retrace_cnt); }
    }
}

/// Sets the function to be called within the video interrupt handler before the VI
/// registers are updated.
/// 
/// Returns the previous callback function, if any.
pub fn set_pre_retrace_callback(callback: RetraceCallback) -> RetraceCallback {
    let cb_ptr = match callback {
        None => {
            let _ = unsafe { ffi::VIDEO_SetPreRetraceCallback(None) };
            ptr::null_mut()
        }
        Some(mut f) => {
            let _ = unsafe { ffi::VIDEO_SetPreRetraceCallback(Some(pre_retrace_callback_bridge)) };
            (&mut f) as *mut fn(u32)
        }
    };

    let prev_cb_ptr = PRE_RETRACE_CB.swap(cb_ptr, Ordering::AcqRel);

    if prev_cb_ptr.is_null() {
        None
    } else {
        // SAFETY: pointer is non-null and always points to a valid rust function
        Some(unsafe { *prev_cb_ptr })
    }
}

/// Wait on the next vertical retrace.
pub fn wait_vsync() {
    unsafe { ffi::VIDEO_WaitVSync() }
}
